import { readFile } from "node:fs/promises";
import { join } from "node:path";
import type { Kit } from "../pdf/build-starkes-kit";
import { CHAPTERS } from "./ep-status";

/** Evidence kits of one chapter (generated by tools/starkes_kits); null for an unknown chapter code. */
export async function loadChapterKits(chapter: string): Promise<Kit[] | null> {
  if (!Object.hasOwn(CHAPTERS, chapter)) return null;
  return JSON.parse(await readFile(join(process.cwd(), "data", "starkes", "kits", `${chapter}.json`), "utf8")) as Kit[];
}
